require_relative "launch_prelude"

module Hecks
  module Tools
    module ProjectCli
      # The text of a launcher, as templates: each `{{name}}` is filled in by `render`.
      module Templates
        include LaunchPrelude

        # A `{{name}}` placeholder; the name is its first group.
        PLACEHOLDER = /\{\{(\w+)\}\}/

        # The whole launcher: its header, the load path, the hand-offs, the entry and the ending.
        LAUNCHER = <<~RUBY.freeze
          {{shebang}}

          # {{name}}'s command line — GENERATED by {{program}}. Do not edit.
          #
          # A launcher, not a CLI: the commands, their arguments and their refusals are
          # projected from the bluebook beside it every time this runs, so a change
          # to the bluebook shows up here without re-minting anything.
          #
          #   {{where}}                  every command, and every question
          #   {{where}} <command> --help    what it wants, and how it refuses

          # When this launcher began, so the usage record can say how long it took to reach the command.
          HECKS_LAUNCHED_AT = Process.clock_gettime(Process::CLOCK_MONOTONIC)
          {{encoding}}$LOAD_PATH.unshift File.expand_path("{{up}}lib", __dir__)
          {{handoff}}
          require "hecks"
          # Every secret a world hands an adapter is masked in whatever this process prints.
          Hecks::Secrets.guard!

          {{entry}}
          {{ending}}
        RUBY

        # An opted-in launcher's middle: usage answered from the projection, a boot only for a
        # line that runs a command.
        DESCRIBED_ENTRY = <<~'RUBY'.freeze
          # Usage is answered from the projected bluebook alone: no adapter is bound and no
          # database is opened. Only a line that runs a command boots the domain,
          # and it boots from what the usage check already loaded.
          domain = {{boot}}
          program = "{{shown}}"
          described = begin
            Hecks.describe(domain)
          rescue StandardError => e
            abort "cannot open {{name}}: #{e.message.strip}"
          end

          # `hecks usage` reads the local record of what this launcher ran; it boots nothing.
          if ARGV.first == "usage"
            known = Hecks::Adapters::Driving::CliRunner.known_names(runtime: described, program: program)
            puts Hecks::Adapters::Driving::UsageLog.summary(known: known)
            exit 0
          end

          text, status, reason = Hecks::Adapters::Driving::CliRunner.usage(
            runtime: described, argv: ARGV, program: program
          )
          unless text
            # A question the world lists under `reads_tap` is answered on a boot that writes nothing.
            read_only = Hecks::Adapters::Driving::ReadOnlyQuestion.for_line?(described, ARGV, "{{name}}")
            runtime = begin
              {{started}}
            rescue StandardError => e
              abort "cannot open {{name}}: #{e.message.strip}"
            end
            # A question the world lists under `streams`, given `--stream`, tails until interrupted.
            streamed = Hecks::Adapters::Driving::CliRunner.stream(runtime: runtime, argv: ARGV, program: program)
            exit streamed unless streamed.nil?
            text, status, reason = Hecks::Adapters::Driving::CliRunner.call(
              runtime: runtime, argv: ARGV, program: program, usage_log: true
            )
          end
        RUBY

        # The middle every launcher had before opted-in ones answered usage alone.
        PLAIN_ENTRY = <<~'RUBY'.freeze
          runtime = begin
            Hecks.boot({{boot}}, install_driving: false)
          rescue StandardError => e
            abort "cannot open {{name}}: #{e.message.lines.first.strip}"
          end

          text, status = Hecks::Adapters::Driving::CliRunner.call(
            runtime: runtime, argv: ARGV, program: "{{shown}}"
          )
        RUBY

        # The lines that send a command a ledger answers to the ledger's own directory. The ledger's
        # name is dropped from the command line, and the boot below reads `ledger`.
        LEDGER_ROUTE = <<~RUBY.freeze

          # A command a ledger answers boots that ledger's directory, not this domain's.
          ledger = { {{routes}} }.fetch(ARGV.first, nil)
          ARGV.shift if ledger
        RUBY

        # The lines that default listed commands to Memory.
        MEMORY_DEFAULT = <<~RUBY.freeze

          # These commands keep nothing worth a database, so they run on Memory unless told otherwise.
          # A person is at them: they wait for their result, say why when they are refused, and print
          # no record when they end well.
          MEMORY_COMMANDS = %w[{{commands}}].freeze
          ENV["HECKS_ENVIRONMENT"] ||= "memory" if MEMORY_COMMANDS.include?(ARGV.first.to_s.chomp("!"))
          ARGV << "--wait" if MEMORY_COMMANDS.include?(ARGV.first.to_s.chomp("!")) && !ARGV.include?("--wait")
        RUBY

        # The lines that put a checkout's launcher on the gems its Gemfile pins. They do nothing
        # beside an installed gem, where no Gemfile stands next to the gemspec, and they leave the
        # gems at hand when the pinned set is not installed.
        PINNED_GEMS = <<~RUBY.freeze

          # In a hecks checkout this runs on the gems the Gemfile pins, as `bundle exec` and CI do.
          # Beside an installed gem, or where that set is not installed, it runs on the gems at hand.
          gemfile = File.expand_path("{{up}}Gemfile", __dir__)
          if File.exist?(File.expand_path("{{up}}hecks.gemspec", __dir__)) && File.exist?(gemfile)
            ENV["BUNDLE_GEMFILE"] ||= gemfile
            begin
              require "bundler/setup"
            rescue LoadError, StandardError
              nil
            end
          end
        RUBY

        # The lines that put a launcher beside a client's domain on the gems its project's Gemfile
        # pins, such as a Hecks checkout the client is built alongside. They do nothing where the
        # project has no Gemfile, and leave the gems at hand when the pinned set is not installed.
        PROJECT_GEMS = <<~RUBY.freeze

          # Where the project's Gemfile pins its gems (a local Hecks among them), this runs on them.
          gemfile = File.expand_path("{{up}}Gemfile", __dir__)
          if File.exist?(gemfile)
            ENV["BUNDLE_GEMFILE"] ||= gemfile
            begin
              require "bundler/setup"
            rescue LoadError, StandardError
              nil
            end
          end
        RUBY

        # Fills a template's `{{name}}` placeholders.
        #
        # @param template [String] the template text
        # @param values [Hash{Symbol => String}] each placeholder's value
        # @return [String] the text with every placeholder replaced
        # @raise [KeyError] if the template names a placeholder `values` lacks
        def render(template, values)
          template.gsub(PLACEHOLDER) { values.fetch(Regexp.last_match(1).to_sym) }
        end
      end
    end
  end
end
